CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, super_admin boolean NOT NULL DEFAULT false, must_change_password boolean NOT NULL DEFAULT true, disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, code text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (user_id uuid NOT NULL REFERENCES users(id), organization_id uuid NOT NULL REFERENCES organizations(id), role text NOT NULL CHECK(role IN ('ORG_ADMIN','DESIGNER','OPERATOR','VIEWER')), PRIMARY KEY(user_id,organization_id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE login_limits (key text PRIMARY KEY, attempts integer NOT NULL, window_start timestamptz NOT NULL);
CREATE TABLE org_units (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), parent_id uuid, kind text NOT NULL CHECK(kind IN ('BRANCH','DEPARTMENT','CLASS','SECTION')), name text NOT NULL, code text NOT NULL, UNIQUE(organization_id,id), UNIQUE(organization_id,kind,code), FOREIGN KEY(organization_id,parent_id) REFERENCES org_units(organization_id,id));
CREATE TABLE field_definitions (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), key text NOT NULL CHECK(key ~ '^[a-z][a-z0-9_]{0,63}$'), label text NOT NULL, type text NOT NULL CHECK(type IN ('text','number','date','boolean')), required boolean NOT NULL DEFAULT false, private boolean NOT NULL DEFAULT true, UNIQUE(organization_id,key), UNIQUE(organization_id,id));
CREATE TABLE people (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), external_id text NOT NULL, name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', designation text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), custom_fields jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,external_id));
CREATE INDEX people_name ON people(organization_id,lower(name));
CREATE INDEX people_custom ON people USING gin(custom_fields);
CREATE TABLE person_units (organization_id uuid NOT NULL, person_id uuid NOT NULL, unit_id uuid NOT NULL, PRIMARY KEY(person_id,unit_id), FOREIGN KEY(organization_id,person_id) REFERENCES people(organization_id,id), FOREIGN KEY(organization_id,unit_id) REFERENCES org_units(organization_id,id));
CREATE TABLE assets (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), kind text NOT NULL CHECK(kind IN ('PHOTO','IMAGE','SIGNATURE','STAMP','LOGO','RENDER')), original_name text NOT NULL DEFAULT '', storage_key text NOT NULL UNIQUE, thumbnail_key text, sha256 text NOT NULL, width integer NOT NULL, height integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id));
CREATE TABLE person_assets (organization_id uuid NOT NULL, person_id uuid NOT NULL, slot text NOT NULL DEFAULT 'photo', asset_id uuid NOT NULL, PRIMARY KEY(person_id,slot), FOREIGN KEY(organization_id,person_id) REFERENCES people(organization_id,id), FOREIGN KEY(organization_id,asset_id) REFERENCES assets(organization_id,id));
CREATE TABLE templates (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, archived boolean NOT NULL DEFAULT false, is_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id));
CREATE UNIQUE INDEX one_default_template ON templates(organization_id) WHERE is_default AND NOT archived;
CREATE TABLE template_versions (id uuid PRIMARY KEY, organization_id uuid NOT NULL, template_id uuid NOT NULL, version integer NOT NULL CHECK(version>0), document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(template_id,version), FOREIGN KEY(organization_id,template_id) REFERENCES templates(organization_id,id));
CREATE TABLE number_sequences (organization_id uuid PRIMARY KEY REFERENCES organizations(id), prefix text NOT NULL DEFAULT 'ID', pattern text NOT NULL DEFAULT '{{prefix}}-{{year}}-{{seq}}', next_value bigint NOT NULL DEFAULT 1, padding integer NOT NULL DEFAULT 6 CHECK(padding BETWEEN 1 AND 18));
CREATE TABLE cards (id uuid PRIMARY KEY, organization_id uuid NOT NULL, person_id uuid NOT NULL, number text NOT NULL, verify_hash text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ACTIVE','PRINTED','EXPIRED','LOST','REPLACED','SUSPENDED','CANCELLED')), expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,number), FOREIGN KEY(organization_id,person_id) REFERENCES people(organization_id,id));
CREATE TABLE card_events (id uuid PRIMARY KEY, organization_id uuid NOT NULL, card_id uuid NOT NULL, type text NOT NULL, actor_id uuid REFERENCES users(id), details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,card_id) REFERENCES cards(organization_id,id));
CREATE TABLE card_renders (id uuid PRIMARY KEY, organization_id uuid NOT NULL, card_id uuid NOT NULL, template_version_id uuid NOT NULL, snapshot jsonb NOT NULL, front_asset_id uuid NOT NULL, back_asset_id uuid, renderer_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,card_id) REFERENCES cards(organization_id,id), FOREIGN KEY(organization_id,template_version_id) REFERENCES template_versions(organization_id,id), FOREIGN KEY(organization_id,front_asset_id) REFERENCES assets(organization_id,id), FOREIGN KEY(organization_id,back_asset_id) REFERENCES assets(organization_id,id));
CREATE TABLE import_batches (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), original_name text NOT NULL, columns jsonb NOT NULL, mapping jsonb, status text NOT NULL CHECK(status IN ('UPLOADED','VALIDATED','IMPORTED')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id));
CREATE TABLE import_rows (organization_id uuid NOT NULL, batch_id uuid NOT NULL, row_number integer NOT NULL, raw jsonb NOT NULL, normalized jsonb, errors jsonb NOT NULL DEFAULT '[]', imported boolean NOT NULL DEFAULT false, PRIMARY KEY(batch_id,row_number), FOREIGN KEY(organization_id,batch_id) REFERENCES import_batches(organization_id,id));
CREATE TABLE audit_events (id uuid PRIMARY KEY, organization_id uuid REFERENCES organizations(id), actor_id uuid REFERENCES users(id), action text NOT NULL, target_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE worker_heartbeats (name text PRIMARY KEY, seen_at timestamptz NOT NULL);
CREATE FUNCTION reject_immutable_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History records are immutable'; END $$;
CREATE TRIGGER immutable_template_versions BEFORE UPDATE OR DELETE ON template_versions FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TRIGGER immutable_card_renders BEFORE UPDATE OR DELETE ON card_renders FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TRIGGER immutable_card_events BEFORE UPDATE OR DELETE ON card_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['org_units','field_definitions','people','person_units','assets','person_assets','templates','template_versions','number_sequences','cards','card_events','card_renders','import_batches','import_rows'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
    EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (organization_id = nullif(current_setting(''app.org_id'',true),'''')::uuid) WITH CHECK (organization_id = nullif(current_setting(''app.org_id'',true),'''')::uuid)',t);
  END LOOP;
END $$;
